  "dispatch.techSignalsText": { de: "Hier siehst du den technischen Weg jeder E-Mail: erfasst, vom Versanddienst übernommen, zugestellt, geöffnet und geklickt. Dieser Bereich beschreibt den Mailtransport – getrennt vom Rechnungsabgleich oben.", en: "This section shows the technical path of each email: recorded, accepted by the delivery service, delivered, opened, and clicked. It describes mail transport separately from the invoice reconciliation above." },
  "dispatch.techSignalsBadge": { de: "Mail-Ereignisse", en: "Mail events" },
  "dispatch.techMeaningTitle": { de: "Was bedeutet „Angenommen“?", en: "What does “accepted” mean?" },
  "dispatch.techMeaningBody": { de: "Der Versanddienst hat die Nachricht übernommen. Das heißt noch nicht automatisch, dass sie bereits im Postfach gelesen wurde. Spätere Signale zeigen Zustellung, Öffnung oder Klick.", en: "The delivery service has accepted the message. This does not automatically mean it has already been read in the inbox. Later signals show delivery, open, or click." },
  "dispatch.techSplitTitle": { de: "Warum Gesamt und angenommen oft gleich sind", en: "Why total and accepted are often the same" },
  "dispatch.techSplitBody": { de: "{total} technische Nachrichten können hier {invoice} Rechnungsmails plus {clarification} Hinweismails bedeuten. Das ist derselbe Versandlauf, nicht doppelte Rechnungen.", en: "{total} technical messages here can mean {invoice} invoice emails plus {clarification} guidance emails. This is the same dispatch run, not duplicate invoices." },
  "dispatch.signalNote": { de: "Öffnungen und Klicks sind technische Hinweise. Der Dokumentabruf im Patientenportal ist das stärkere Signal.", en: "Opens and clicks are technical indicators. Portal document access is the stronger signal." },
