  "dispatch.statusHint.queued": { de: "Die Nachricht ist vorgemerkt, aber noch nicht vom Versanddienst übernommen.", en: "The message is queued but has not yet been accepted by the delivery service." },
  "dispatch.statusHint.accepted": { de: "Der Versanddienst hat die Nachricht übernommen. Ob sie bereits im empfangenden Postfach angekommen ist, zeigen erst spätere Signale.", en: "The delivery service has accepted the message. Later signals show whether it has already reached the receiving inbox." },
  "dispatch.statusHint.delivered": { de: "Der empfangende Mailserver hat die Nachricht angenommen. Das ist stärker als „angenommen“, aber noch kein Beweis dafür, dass ein Mensch sie gelesen hat.", en: "The receiving mail server has accepted the message. This is stronger than “accepted” but still not proof that a person has read it." },
  "dispatch.statusHint.opened": { de: "Ein Öffnungssignal wurde technisch erkannt. Das ist ein brauchbarer Hinweis, aber nicht in jedem Fall ein menschlicher Lesebeweis.", en: "An open signal was technically detected. This is a useful indicator, but not always definitive proof that a person read it." },
  "dispatch.statusHint.clicked": { de: "Ein Link aus der Nachricht wurde aufgerufen. Für Rechnungen bleibt der tatsächliche Dokumentabruf im Patientenportal das stärkere Signal.", en: "A link from the message was opened. For invoices, actual document access in the patient portal remains the stronger signal." },
  "dispatch.statusHint.delayed": { de: "Die Zustellung ist noch offen oder verzögert. Es liegt noch kein bestätigtes Empfangssignal vor.", en: "Delivery is still pending or delayed. There is no confirmed receipt signal yet." },
  "dispatch.statusHint.failed": { de: "Die Nachricht konnte technisch nicht sauber zugestellt werden oder wurde unterdrückt. Hier braucht es Nacharbeit bei Adresse, Transport oder Kontaktbasis.", en: "The message could not be delivered cleanly or was suppressed. This requires follow-up on the address, transport, or contact basis." },
  "dispatch.statusHint.default": { de: "Dieser Status beschreibt einen technischen Zwischenschritt im Versandlauf.", en: "This status describes a technical step in the delivery flow." },
