  "clarification.subject": { de: "Wichtige Information zu deinem Rechnungszugang – ohne App-Installation", en: "Important information about your invoice access – no app installation required" },
  "clarification.preheader": { de: "So öffnest du das offizielle Patientenportal im Browser und bekommst Hilfe beim Zugang.", en: "How to open the official patient portal in your browser and get help with access." },
  "clarification.eyebrow": { de: "Kieferorthopädie in Leipzig", en: "Orthodontics in Leipzig" },
  "clarification.kicker": { de: "Information zu deinem Patientenportal Anima Cura", en: "Information about your Anima Cura patient portal" },
  "clarification.headline": { de: "Dein Rechnungszugang. Einfach im Browser.", en: "Your invoice access. Simply in your browser." },
  "clarification.greeting": { de: "Hallo,", en: "Hello," },
  "clarification.intro": { de: "Uns haben Fragen zu Anmeldung und Rechnungen erreicht. Unsere bisherigen Hinweise waren nicht überall eindeutig genug. Deshalb erklären wir den Zugang hier noch einmal klar und vollständig.", en: "We have received questions about sign-in and invoices. Some of our earlier information was not clear enough, so this message explains access clearly and completely." },
  "clarification.official": { de: "Anima Cura ist das offizielle digitale Patientenportal der KFO-Praxis Dr. Schubert. Dort findest du deine bereitgestellten Unterlagen und Rechnungen.", en: "Anima Cura is the official digital patient portal of Dr. Schubert's orthodontic practice. It contains the documents and invoices made available to you." },
  "clarification.noInstallTitle": { de: "Ohne Installation. Ohne WhatsApp.", en: "No installation. No WhatsApp." },
  "clarification.noInstallBody": { de: "Anima Cura ist eine Web-App. Du öffnest sie direkt im Internetbrowser auf Smartphone, Tablet oder Computer. Ein Download aus dem App Store ist nicht nötig; das Speichern auf dem Startbildschirm ist freiwillig.", en: "Anima Cura is a web app. Open it directly in the browser on a smartphone, tablet, or computer. No app-store download is required; saving it to the home screen is optional." },
  "clarification.cta": { de: "Patientenportal im Browser öffnen", en: "Open patient portal in browser" },
  "clarification.digitalTitle": { de: "Warum die Praxis auf digitale Rechnungen umstellt", en: "Why the practice is switching to digital invoices" },
  "clarification.digitalBody": { de: "Du musst keine App aus einem App Store installieren. Die Praxis stellt Rechnungen ab diesem Quartal standardmäßig digital im geschützten Patientenportal bereit. Während der Umstellung unterstützen wir dich. Wenn dir ein digitaler Zugang nicht möglich ist, melde dich bitte frühzeitig bei uns.", en: "You do not need to install an app from an app store. From this quarter, the practice provides invoices digitally in the protected patient portal by default. We will support you during the transition. If digital access is not possible for you, please contact us early." },
  "clarification.benefitsTitle": { de: "Das bringt dir der digitale Zugang", en: "Benefits of digital access" },
  "clarification.benefit1": { de: "Jederzeit Zugriff auf bereitgestellte Dokumente und Rechnungen", en: "Access to available documents and invoices at any time" },
  "clarification.benefit2": { de: "Benachrichtigungen, sobald etwas Neues vorliegt", en: "Notifications when something new is available" },
  "clarification.benefit3": { de: "Fristen und offene Vorgänge bleiben übersichtlich", en: "Clear overview of deadlines and open items" },
  "clarification.benefit4": { de: "Unnötige Zahlungserinnerungen und Folgefragen werden vermieden", en: "Avoid unnecessary payment reminders and follow-up questions" },
  "clarification.benefit5": { de: "Banking-QR und Überweisungsdaten stehen direkt bei der Rechnung bereit", en: "Banking QR and transfer details are available with the invoice" },
  "clarification.verifyTitle": { de: "Du möchtest die Adresse selbst prüfen?", en: "Want to verify the address yourself?" },
  "clarification.verifyBody": { de: "Du musst keinen Link aus einer E-Mail anklicken. Gib animacura.io/patient/login selbst in die Adresszeile deines Browsers ein. Achte auf die genaue Domain animacura.io. Wir fragen dich niemals per E-Mail, SMS oder Telefon nach deinem Passwort oder Sicherheitscode.", en: "You do not need to click a link in an email. Type animacura.io/patient/login into your browser address bar. Check the exact animacura.io domain. We will never ask for your password or security code by email, text message, or phone." },
  "clarification.accessTitle": { de: "So kommst du an deine Unterlagen", en: "How to access your documents" },
  "clarification.accessExisting": { de: "Zugang vorhanden: Melde dich mit deinen Anima-Cura-Zugangsdaten an. Bereitgestellte Rechnungen findest du unter Dokumente.", en: "Access already available: Sign in with your Anima Cura credentials. Available invoices are listed under Documents." },
  "clarification.accessPassword": { de: "Passwort vergessen: Wähle Passwort vergessen?. Deine Anima-Cura-Anmeldeadresse ist nur deine Kennung, kein E-Mail-Postfach. Der Sicherheitscode geht an deine bei der Praxis hinterlegte private E-Mail-Adresse.", en: "Forgot your password: Select Forgot password?. Your Anima Cura sign-in address is only your identifier, not an email inbox. The security code is sent to your private email address registered with the practice." },
  "clarification.accessMissing": { de: "Noch kein Zugang oder Anmeldeadresse unbekannt: Wähle Keine Zugangsdaten? Zugang herstellen. Du benötigst Patientennummer, Geburtsdatum und die hinterlegte private Kontakt-E-Mail. Ein neuer Anamnesebogen ist nicht nötig.", en: "No access yet or sign-in address unknown: Select No access details? Restore access. You need the patient number, date of birth, and registered private contact email. You do not need to complete a new medical history form." },
  "clarification.paymentTitle": { de: "Bereits bezahlt, Raten oder Lastschrift?", en: "Already paid, installments, or direct debit?" },
  "clarification.paymentBody": { de: "Eine Rechnungsbenachrichtigung bedeutet nicht automatisch, dass du zusätzlich überweisen musst. Bereits geleistete Zahlungen sind nicht doppelt zu leisten. Für Raten oder Lastschrift gilt die Vereinbarung zur jeweiligen Rechnung. Bei einem unklaren Zahlungsstand schreibe uns zur Prüfung.", en: "An invoice notification does not automatically mean that you need to make an additional payment. Do not pay an amount twice. Existing installment or direct-debit agreements for the invoice remain applicable. Contact us if the payment status is unclear." },
  "clarification.helpTitle": { de: "Wir helfen dir beim Zugang", en: "We help with access" },
  "clarification.helpBody": { de: "Anmeldeadresse unbekannt, kein Code angekommen oder digitaler Zugang nicht möglich? Antworte direkt auf diese E-Mail oder schreibe an praxisteam@animacura.io. Sende niemals Passwörter, Sicherheitscodes oder unaufgefordert medizinische Unterlagen.", en: "Sign-in address unknown, no code received, or digital access not possible? Reply directly to this email or write to praxisteam@animacura.io. Never send passwords, security codes, or unsolicited medical documents." },
  "clarification.signature": { de: "Liebe Grüße\nDein Praxisteam Dr. Schubert", en: "Kind regards\nYour Dr. Schubert practice team" },
  "accessHelp.open": { de: "Hilfe", en: "Help" },
  "accessHelp.close": { de: "Hilfe schließen", en: "Close help" },
