  "patientRecovery.title": { de: "Neues Passwort einrichten", en: "Set a new password" },
  "patientRecovery.intro": { de: "Gib deine persönliche Anima-Cura-Anmeldeadresse ein. Den Sicherheitscode senden wir an deine private Kontakt-E-Mail.", en: "Enter your personal Anima Cura sign-in address. We will send the security code to your private contact email." },
