  "patientRecovery.loginAddressHint": { de: "Diese Adresse endet meist auf @animacura.de und dient nur als Benutzername. Sie kann keine E-Mails empfangen.", en: "This address usually ends in @animacura.de and is only your username. It cannot receive email." },
  "patientRecovery.codeDestination": { de: "Der Code geht automatisch an die private E-Mail-Adresse, die bei der Praxis hinterlegt ist – zum Beispiel Gmail, GMX oder Web.de.", en: "The code is automatically sent to the private email address registered with the practice, such as Gmail, GMX, or Web.de." },
  "patientRecovery.unknownLogin": { de: "Anmeldeadresse unbekannt? Zugang mit Patientennummer herstellen", en: "Unknown sign-in address? Restore access with your patient number" },
  "patientRecovery.sending": { de: "Wird gesendet…", en: "Sending…" },
  "patientRecovery.saving": { de: "Wird gespeichert…", en: "Saving…" },
  "patientRecovery.codeSent": { de: "Wenn die Anmeldeadresse deinem Zugang zugeordnet ist, kommt der Code jetzt an deine private Kontakt-E-Mail. Prüfe bitte auch den Spam-Ordner.", en: "If the sign-in address belongs to your account, the code is now being sent to your private contact email. Please also check your spam folder." },
