  "patientRecovery.invalidCode": { de: "Der Sicherheitscode ist falsch oder abgelaufen. Fordere bei Bedarf einen neuen Code an.", en: "The security code is incorrect or expired. Request a new code if needed." },
  "patientRecovery.unavailable": { de: "Der Zugangsdienst ist gerade nicht erreichbar. Bitte versuche es in wenigen Minuten erneut.", en: "The access service is currently unavailable. Try again in a few minutes." },
  "patientRecovery.emailSubject": { de: "Dein Sicherheitscode für Anima Cura", en: "Your Anima Cura security code" },
  "patientRecovery.emailTitle": { de: "Passwort sicher neu einrichten", en: "Securely set a new password" },
  "patientRecovery.emailIntro": { de: "Öffne über den Button die Anima-Cura-Anwendung und gib dort diesen Sicherheitscode ein, um dein neues Passwort festzulegen.", en: "Open the Anima Cura application using the button and enter this security code there to set your new password." },
  "patientRecovery.emailExpiry": { de: "Der Code ist 30 Minuten gültig und kann nur einmal verwendet werden.", en: "The code is valid for 30 minutes and can only be used once." },
  "patientRecovery.emailWarning": { de: "Du hast keinen neuen Code angefordert? Dann ignoriere diese Nachricht. Teile den Code niemals telefonisch oder per E-Mail mit anderen.", en: "Did not request a new code? Ignore this message. Never share the code by phone or email." },
  "patientRecovery.emailSignature": { de: "Liebe Grüße, dein Praxisteam Dr. Schubert", en: "Kind regards, Dr. Schubert's practice team" },
  "patientActivation.open": { de: "Keine Zugangsdaten? Zugang herstellen", en: "No sign-in details? Set up access" },
  "patientActivation.openHint": { de: "Auch wenn du deine Anima-Cura-Anmeldeadresse nicht kennst. Kein neuer Anamnesebogen nötig.", en: "Also works if you do not know your Anima Cura sign-in address. No new medical history form required." },
  "patientActivation.title": { de: "Zugang zur Patientenakte herstellen", en: "Set up access to your patient record" },
  "patientActivation.intro": { de: "Du brauchst keine Anima-Cura-Anmeldeadresse. Mit den folgenden Angaben kannst du deinen Zugang aktivieren oder wiederherstellen und ein eigenes Passwort festlegen.", en: "You do not need an Anima Cura sign-in address. Use the following details to activate or restore access and set your own password." },
  "patientActivation.patientNumber": { de: "Patientennummer", en: "Patient number" },
  "patientActivation.patientNumberHint": { de: "Die Nummer steht auf der Rechnung oder den Praxisunterlagen. Für dein Kind: Verwende dessen Patientennummer und Geburtsdatum.", en: "Find this number on the invoice or practice documents. For your child, use their patient number and date of birth." },
  "patientActivation.birthDate": { de: "Geburtsdatum der behandelten Person", en: "Patient’s date of birth" },
  "patientActivation.contactEmail": { de: "Private Kontakt-E-Mail", en: "Private contact email" },
  "patientActivation.contactEmailHint": { de: "Deine echte E-Mail-Adresse, die für diese Patientenakte bei der Praxis hinterlegt ist. Dorthin kommt der Code – nicht an eine @animacura.de-Anmeldeadresse.", en: "Your real email address registered with the practice for this patient record. The code goes there, not to an @animacura.de sign-in address." },
  "patientActivation.missingDetails": { de: "Patientennummer fehlt oder Kontaktadresse geändert? Hilfe beim Zugang anfordern", en: "Missing patient number or changed contact email? Request help with access" },
  "patientActivation.privacy": { de: "Wir gleichen diese Angaben nur mit deiner bestehenden Patientenakte ab. Es wird keine neue Akte und kein neuer Anamnesebogen erstellt.", en: "We only match these details to your existing patient record. No new record or medical history form is created." },
  "patientActivation.requestCode": { de: "Sicherheitscode anfordern", en: "Request security code" },
