  "patientActivation.codeSent": { de: "Wenn alle Angaben zur bestehenden Patientenakte passen, kommt der Code jetzt an deine private Kontakt-E-Mail. Prüfe bitte auch den Spam-Ordner.", en: "If all details match the existing patient record, the code is now being sent to your private contact email. Please also check your spam folder." },
