  "billing.issue.share_allocation_unsupported": { de: "Patientenanteil für private Leistungen getrennt prüfen; kein pauschaler Kassenanteil auf GOZ.", en: "Review the patient share for private services separately; do not apply a blanket insurance share to GOZ fees." },
