  "billing.draftPayment": { de: "Zahlungsart, Zahlungsfrist und Verwendungszweck werden erst mit der freigegebenen Rechnung festgelegt. Diesen Entwurf nicht zur Zahlung verwenden.", en: "Payment method, due date and payment reference are assigned with the approved invoice. Do not use this draft for payment." },
